// ../ABConverter/ABConvertManager.ts
var ABConvertManager = class {
  constructor() {
    this.list_abConvert = [];
    this.m_renderMarkdownFn = (markdown, el) => {
      el.classList.add("markdown-rendered");
      console.error("AnyBlockError: \u8BF7\u5148\u5236\u5B9A/\u91CD\u5B9A\u4E49md\u6E32\u67D3\u5668");
    };
    if (typeof obsidian == "undefined" && typeof app == "undefined") {
      console.log("[environment]: markdown-it, without obsidian");
    } else {
      console.log("[environment]: obsidian");
    }
  }
  static getInstance() {
    if (!ABConvertManager.m_instance) {
      ABConvertManager.m_instance = new ABConvertManager();
    }
    return ABConvertManager.m_instance;
  }
  getConvertOptions() {
    return this.list_abConvert.filter((item) => {
      return item.default;
    }).map((item) => {
      return { id: item.default, name: item.name };
    });
  }
  redefine_renderMarkdown(callback) {
    this.m_renderMarkdownFn = callback;
  }
  static autoABConvert(el, header, content3, selectorName = "") {
    let prev_result = content3;
    let prev_type = "string";
    let prev_type2 = "string" /* text */;
    let prev_processor;
    let prev3 = {
      prev_result,
      prev_type,
      prev_type2,
      prev_processor
    };
    if (false)
      ABConvertManager.startTime = performance.now();
    {
      header = autoABAlias(header, selectorName, prev_result);
      let list_header = header.split("|");
      prev_result = this.autoABConvert_runConvert(el, list_header, prev3);
      this.autoABConvert_last(el, header, selectorName, prev3);
    }
    if (false) {
      const endTime = performance.now();
      console.log(`Takes ${(endTime - ABConvertManager.startTime).toFixed(2)} ms when selector "${selectorName}" header "${header}"`);
    }
  }
  static autoABConvert_runConvert(el, list_header, prev3) {
    for (let item_header of list_header) {
      for (let abReplaceProcessor of ABConvertManager.getInstance().list_abConvert) {
        if (typeof abReplaceProcessor.match == "string") {
          if (abReplaceProcessor.match != item_header)
            continue;
        } else {
          if (!abReplaceProcessor.match.test(item_header))
            continue;
        }
        if (abReplaceProcessor.process_alias) {
          let alias = abReplaceProcessor.process_alias;
          (() => {
            if (abReplaceProcessor.process_alias.indexOf("%") < 0)
              return;
            if (typeof abReplaceProcessor.match == "string")
              return;
            const matchs = item_header.match(abReplaceProcessor.match);
            if (!matchs)
              return;
            const len = matchs.length;
            if (len == 1)
              return;
            for (let i = 1; i < len; i++) {
              if (!matchs[i])
                continue;
              alias = alias.replace(RegExp(`%${i}`), matchs[i]);
            }
          })();
          prev3.prev_result = this.autoABConvert_runConvert(el, alias.split("|"), prev3);
        } else if (abReplaceProcessor.process) {
          if (abReplaceProcessor.process_param != prev3.prev_type2) {
            if (abReplaceProcessor.process_param == "HTMLElement" /* el */ && prev3.prev_type2 == "string" /* text */) {
              const subEl = document.createElement("div");
              el.appendChild(subEl);
              ABConvertManager.getInstance().m_renderMarkdownFn(prev3.prev_result, subEl);
              prev3.prev_result = el;
              prev3.prev_type = typeof prev3.prev_result;
              prev3.prev_type2 = "HTMLElement" /* el */;
              prev3.prev_processor = "md";
            } else if (abReplaceProcessor.process_param == "string" /* text */ && (prev3.prev_type2 == "array" /* list_stream */ || prev3.prev_type2 == "array2" /* c2list_stream */)) {
              prev3.prev_result = JSON.stringify(prev3.prev_result, null, 2);
              prev3.prev_type = typeof prev3.prev_result;
              prev3.prev_type2 = "string" /* text */;
              prev3.prev_processor = "stream to text";
            } else if (abReplaceProcessor.process_param == "string" /* text */ && prev3.prev_type2 == "json_string" /* json */) {
              prev3.prev_type2 = "string" /* text */;
              prev3.prev_processor = "json to text";
            } else {
              console.warn(`\u5904\u7406\u5668\u8F93\u5165\u7C7B\u578B\u9519\u8BEF, id:${abReplaceProcessor.id}, virtualParam:${abReplaceProcessor.process_param}, realParam:${prev3.prev_type2}`);
              break;
            }
          }
          prev3.prev_result = abReplaceProcessor.process(el, item_header, prev3.prev_result);
          prev3.prev_type = typeof prev3.prev_result;
          prev3.prev_type2 = abReplaceProcessor.process_return;
          prev3.prev_processor = abReplaceProcessor.process;
        } else {
          console.warn("\u5904\u7406\u5668\u5FC5\u987B\u5B9E\u73B0process\u6216process_alias\u65B9\u6CD5");
        }
      }
    }
    return prev3;
  }
  static autoABConvert_last(el, header, selectorName, prev3) {
    if (prev3.prev_type == "string" && prev3.prev_type2 == "string" /* text */) {
      const subEl = document.createElement("div");
      el.appendChild(subEl);
      ABConvertManager.getInstance().m_renderMarkdownFn(prev3.prev_result, subEl);
      prev3.prev_result = el;
      prev3.prev_type = "object";
      prev3.prev_type2 = "HTMLElement" /* el */;
      prev3.process = "md";
    } else if (prev3.prev_type == "string" && prev3.prev_type2 == "json_string" /* json */) {
      const code_str = "```json\n" + prev3.prev_result + "\n```\n";
      const subEl = document.createElement("div");
      el.appendChild(subEl);
      ABConvertManager.getInstance().m_renderMarkdownFn(code_str, subEl);
      prev3.prev_result = el;
      prev3.prev_type = "object";
      prev3.prev_type2 = "HTMLElement" /* el */;
      prev3.process = "show_json";
    } else if (prev3.prev_type == "object" && (prev3.prev_type2 == "array" /* list_stream */ || prev3.prev_type2 == "array2" /* c2list_stream */ || prev3.prev_type2 == "json_string" /* json */)) {
      const code_str = "```json\n" + JSON.stringify(prev3.prev_result, null, 2) + "\n```\n";
      const subEl = document.createElement("div");
      el.appendChild(subEl);
      ABConvertManager.getInstance().m_renderMarkdownFn(code_str, subEl);
      prev3.prev_result = el;
      prev3.prev_type = "object";
      prev3.prev_type2 = "HTMLElement" /* el */;
      prev3.process = "show_listStream";
    } else if (prev3.prev_type == "object" && prev3.prev_type2 == "HTMLElement" /* el */) {
      return prev3;
    } else {
      console.warn("other type in tail, can not tail processor:", prev3.prev_type, prev3.prev_type2, prev3.prev_result);
    }
    return prev3;
  }
};

