function listdata2dirdata(list3) {
  const is_have_vbar = [];
  const newlist = [];
  for (let i = 0; i < list3.length; i++) {
    const item = list3[i];
    let type3;
    if (item.content.endsWith("/")) {
      type3 = "folder";
    } else {
      const parts = item.content.split(".");
      if (parts.length === 0 || parts[parts.length - 1] === "")
        type3 = "";
      else
        type3 = parts[parts.length - 1];
    }
    let is_last = true;
    for (let j = i + 1; j < list3.length; j++) {
      if (list3[j].level < item.level) {
        is_last = true;
        break;
      } else if (list3[j].level == item.level) {
        is_last = false;
        break;
      } else {
        continue;
      }
    }
    is_have_vbar[item.level] = !is_last;
    let pre_as_text = "";
    if (item.level > 1) {
      for (let i2 = 1; i2 < item.level; i2++) {
        if (!is_have_vbar.hasOwnProperty(i2))
          pre_as_text += "[e]";
        else if (is_have_vbar[i2])
          pre_as_text += "|  ";
        else
          pre_as_text += "   ";
      }
    }
    newlist.push({
      content: item.content,
      level: item.level,
      type: type3,
      is_last,
      pre_as_text
    });
  }
  return newlist;
}
var abc_list2astreeH = ABConvert.factory({
  id: "list2astreeH",
  name: "\u5217\u8868\u5230sacii\u76EE\u5F55\u6811",
  process_param: "string" /* text */,
  process_return: "string" /* text */,
  process: (el, header, content3) => {
    let listdata = ListProcess.list2data(content3);
    listdata = ListProcess.data2strict(listdata);
    const dirlistdata = listdata2dirdata(listdata);
    let newContent = "";
    for (const item of dirlistdata) {
      if (item.level == 0) {
        newContent += item.content + "\n";
      } else {
        newContent += item.pre_as_text + (item.is_last ? "\u2514\u2500 " : "\u251C\u2500 ") + item.content + "\n";
      }
    }
    newContent = newContent.trimEnd();
    return newContent;
  }
});

